"""Collect location strings; soft-filter rows with no plausible profile city match."""

from __future__ import annotations

import re
import time

from v2.shared.observability.sli_observe import passed, reject, sli_observe
from v2.shared.patterns.worker_runtime import ExecutionResult

MODULE_NAME = "job_matcher__resolve_location"
MODULE_TYPE = "filter"
REJECTION_REASONS = {"LOCATION_NOT_IN_PROFILE"}
ERROR_REASONS: set[str] = set()
WARNING_REASONS: set[str] = set()

_PLACEHOLDER_RE = re.compile(r"^\d+\s+location", re.IGNORECASE)
_REMOTE_RE = re.compile(r"\b(remote|home.based|work from home|wfh|home based)\b", re.IGNORECASE)


def _collect_location_strings(row: dict) -> list[str]:
    """Gather all location text from all structured_job location fields and scraped.location."""
    strings: list[str] = []
    page = row.get("page") or {}
    sj = page.get("structured_job") or {}

    # sj.locations (array) — used by some job pages
    for loc in sj.get("locations") or []:
        if loc and str(loc).strip():
            strings.append(str(loc).strip())

    # sj.location (singular string) + sj.additional_locations (array) — used by others
    sj_loc = (sj.get("location") or "").strip()
    if sj_loc:
        strings.append(sj_loc)
    for loc in sj.get("additional_locations") or []:
        if loc and str(loc).strip():
            strings.append(str(loc).strip())

    # scraped.location, skip "N Locations" placeholder
    scraped = (row.get("location") or "").strip()
    if scraped and not _PLACEHOLDER_RE.match(scraped):
        strings.append(scraped)

    return strings


def _build_profile_city_set(locations: list) -> frozenset[str]:
    """All city names from profile locations (name + includes), lower-cased."""
    cities: set[str] = set()
    for loc in locations:
        cities.add((loc.get("name") or "").lower())
        for inc in loc.get("includes") or []:
            if inc:
                cities.add(inc.lower())
    return frozenset(c for c in cities if c)


def _has_city_token(strings: list[str], profile_cities: frozenset[str]) -> bool:
    """True if any token from any location string appears in the profile city set."""
    for s in strings:
        for token in re.split(r"[\s,/|]+", s.lower()):
            token = token.strip()
            if token and token in profile_cities:
                return True
    return False


def main(context: dict, prev_data: list[dict]) -> ExecutionResult:
    trace_id: str = context.get("trace_id")
    start_time = time.time()

    profile_cities = _build_profile_city_set(context["profile"].get("locations") or [])
    has_remote_profile = any(loc.get("type") == "remote" for loc in context["profile"].get("locations") or [])

    for row in prev_data:
        strings = _collect_location_strings(row)
        row["location_strings"] = strings

        is_remote = any(_REMOTE_RE.search(s) for s in strings)
        row["is_remote_hint"] = is_remote

        if is_remote and has_remote_profile:
            continue
        if _has_city_token(strings, profile_cities):
            continue
        reject(row, "LOCATION_NOT_IN_PROFILE")

    sli_observe(prev_data, MODULE_NAME, start_time, trace_id)
    return ExecutionResult(
        trace_id=trace_id,
        script_span_id=f"{MODULE_NAME}_{trace_id}",
        data=passed(prev_data),
        artifacts={},
        metrics={},
    )

from __future__ import annotations

import json
from pathlib import Path

import pytest


@pytest.fixture
def ctx(tmp_path, monkeypatch):
    """Minimal context dict with SLI redirected to tmp_path. trace_id='t'."""
    monkeypatch.setenv("ILLUMINI_RUNS_DIR", str(tmp_path))
    return {"trace_id": "t"}


@pytest.fixture
def profile():
    """Minimal recruiter profile for v2 module tests."""
    return {
        "profile_id": "test",
        "companies": [
            {"name": "Acme Corp", "industry": None},
            {"name": "Siemens Energy", "industry": "Engineering"},
        ],
        "titles": ["Controls Engineer", "Electrical Engineer", "Quality Engineer"],
        "locations": [
            {
                "name": "Warrington",
                "type": "sub_region",
                "includes": ["Warrington", "Runcorn", "Knutsford"],
                "country": "United Kingdom",
            },
            {
                "name": "Remote (UK)",
                "type": "remote",
                "includes": ["Remote", "Home-based"],
                "country": "United Kingdom",
            },
        ],
    }


def make_row(
    job_id: str = "J001",
    title: str = "Controls Engineer",
    company: str = "Acme Corp",
    location: str = "Warrington",
    **kwargs,
) -> dict:
    """Build a minimal v2 row (post-load_job_feed shape)."""
    from v2.shared.observability.sli_observe import META_OUTCOME

    return {
        "job_id": job_id,
        "title": title,
        "company": company,
        "location": location,
        "salary_gbp": None,
        "source_url": "",
        "page": {"http_status": 200},
        META_OUTCOME: "pass",
        **kwargs,
    }


def read_sli(tmp_path: Path, trace_id: str = "t") -> list[dict]:
    """Read SLI events written during a module call (mirrors tests/v1/helpers.py)."""
    path = tmp_path / trace_id / "sli_events.jsonl"
    if not path.exists():
        return []
    return [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]

"""Shared golden-dataset fixtures for v2 normalization tests."""

from __future__ import annotations

import json
from pathlib import Path

import pytest

from v2.shared.observability.sli_observe import META_OUTCOME

_GOLDEN_DIR = Path("tests/v2/golden-dataset")
_JOBS_PATH = _GOLDEN_DIR / "jobs.jsonl"
_LABELS_PATH = _GOLDEN_DIR / "labelled_300.jsonl"
_SEARCH_INPUTS = _GOLDEN_DIR / "user_search_inputs"

def fresh_rows(rows: list[dict]) -> list[dict]:
    """Shallow-copy rows and reset META_OUTCOME='pass' for a clean module run."""
    out = [r.copy() for r in rows]
    for r in out:
        r[META_OUTCOME] = "pass"
    return out


def _raw_to_row(raw: dict) -> dict:
    scraped = raw.get("scraped") or {}
    return {
        "job_id": raw["job_id"],
        "title": scraped.get("title", "").strip(),
        "company": scraped.get("company", "").strip(),
        "location": scraped.get("location", "").strip(),
        "salary_gbp": None,
        "source_url": raw.get("source_url", ""),
        "page": raw.get("page") or {},
        META_OUTCOME: "pass",
    }


@pytest.fixture(scope="module")
def golden_rows():
    """All 300 golden-dataset jobs converted to v2 row shape."""
    raws = [
        json.loads(line)
        for line in _JOBS_PATH.read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    return [_raw_to_row(r) for r in raws]


@pytest.fixture(scope="module")
def labels():
    """Dict {job_id: label_dict} for all 300 labelled jobs."""
    return {
        json.loads(line)["job_id"]: json.loads(line)
        for line in _LABELS_PATH.read_text(encoding="utf-8").splitlines()
        if line.strip()
    }


@pytest.fixture(scope="module")
def profile_a():
    """Real profile_a loaded from golden-dataset user_search_inputs/."""
    from v2.shared.patterns.worker_runtime import load_search_inputs

    return dict(load_search_inputs(_SEARCH_INPUTS))["profile_a"]


@pytest.fixture(scope="module")
def yes_ids(labels):
    """Frozenset of job_ids labelled 'yes' (18 jobs)."""
    return frozenset(jid for jid, lbl in labels.items() if lbl["decision"] == "yes")


@pytest.fixture(scope="module")
def dead_link_ids(labels):
    """Jobs whose label reason mentions '404' or '410' (29 jobs)."""
    return frozenset(
        jid
        for jid, lbl in labels.items()
        if "404" in lbl.get("reason", "") or "410" in lbl.get("reason", "")
    )


@pytest.fixture
def gctx(tmp_path, monkeypatch, profile_a):
    """Function-scoped context: real profile_a + SLI redirected to tmp_path."""
    monkeypatch.setenv("ILLUMINI_RUNS_DIR", str(tmp_path))
    return {"trace_id": "golden", "profile": profile_a}

