import json

jobs = {}
for line in open('tests/v2/golden-dataset/jobs.jsonl'):
    j = json.loads(line)
    jobs[j['job_id']] = j

labels = {}
for line in open('tests/v2/golden-dataset/labelled_300.jsonl'):
    j = json.loads(line)
    labels[j['job_id']] = j

for jid in ['J229510', 'J576140', 'J809819']:
    j = jobs.get(jid)
    if not j:
        print(f'{jid} NOT IN jobs.jsonl'); continue
    lbl = labels.get(jid, {})
    s = j.get('scraped') or {}
    p = j.get('page') or {}
    sj = p.get('structured_job') or {}
    print(f'=== {jid} | decision: {lbl.get(\"decision\")} | reason: {lbl.get(\"reason\",\"\")[:80]}')
    print(f'  scraped.location: {s.get(\"location\")}')
    print(f'  scraped.title:    {s.get(\"title\")}')
    print(f'  scraped.company:  {s.get(\"company\")}')
    print(f'  sj.location: {sj.get(\"location\")}')
    print(f'  sj.locations: {sj.get(\"locations\")}')
    print(f'  sj.additional_locations: {sj.get(\"additional_locations\")}')
    print()
"

